var wordBreak = function(s, wordDict) {
    const words = new Set(wordDict);
    const n = s.length;
    const dp = new Uint8Array(n + 1);
    dp[0] = 1;
    for (let i = 1; i <= n; ++i) {
        for (let j = 0; j < i; ++j) {
            if (dp[j] && words.has(s.slice(j, i))) {
                dp[i] = 1;
                break;
            }
        }
    }
    return dp[n] === 1;
};
